grader.code:
// Names: accents, case, "left/right", "the" and "muscle/musculus" don't matter; one typo is half credit.
const STOP = /\b(the|left|right|muscle|musculus|musculo|m|esquerdo|esquerda|direito|direita|do|da|de|dos|das|o|a|os|as)\b/g;
const norm = (s) => std.normalize(String(s ?? "")).normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .replace(/[^a-z0-9 ]+/g, " ").replace(STOP, " ").replace(/\s+/g, " ").trim();
const lev = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1); // swapped letters = one typo
  }
  return d[a.length][b.length];
};
// Side matters when the name says one: "right kidney" for the left kidney is wrong, "kidney" alone is fine.
const sideOf = (s) => {
  const t = std.normalize(String(s ?? "")).normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const l = /\b(left|esquerd[oa]s?|sinistr\w*)\b/.test(t), r = /\b(right|direit[oa]s?|dext\w*)\b/.test(t);
  return l === r ? null : l ? "L" : "R";
};
const sideClash = (given, correct) => { const a = sideOf(given), b = sideOf(correct); return !!a && !!b && a !== b; };
const the = (s) => { s = String(s ?? ""); return `the ${s.charAt(0).toLowerCase()}${s.slice(1)}`; };
const labels = key.labels ?? [];
const target = key.target ?? [];

if (view.mode === "name") {
  const g = norm(answer);
  if (!g) return { score: 0, feedback: "No answer." };
  const names = key.accept ?? [key.answer];
  if (sideClash(answer, key.answer)) return { score: 0, feedback: `Wrong side: the lit-up one is ${the(key.answer)}.` };
  if (names.some((n) => norm(n) === g)) return { score: 1 };
  const other = labels.find((n, i) => norm(n) === g && !target.includes(i) && norm(n) !== norm(key.answer));
  if (other) return { score: 0, feedback: `${other} is on this model too, but the lit-up one is ${the(key.answer)}.` };
  const close = names.find((n) => { const m = norm(n); return m.length >= 6 && lev(m, g) <= (m.length >= 14 ? 2 : 1); });
  if (close) return { score: 0.5, feedback: `Almost: it's spelled ${key.answer}.` };
  return { score: 0, feedback: `It's ${the(key.answer)}.` };
}

if (view.mode === "choose") {
  if (answer == null || answer === "") return { score: 0, feedback: "No choice made." };
  if (norm(answer) === norm(key.answer) && !sideClash(answer, key.answer)) return { score: 1 };
  return { score: 0, feedback: `You chose ${the(answer)}; the highlighted one is ${the(key.answer)}.` };
}

if (view.mode === "locate") {
  const p = answer && typeof answer === "object" ? Number(answer.part) : NaN;
  if (!Number.isInteger(p) || p < 0) return { score: 0, feedback: "Nothing picked on the model." };
  if (target.includes(p)) return { score: 1, details: { picked: p } };
  const name = labels[p];
  return { score: 0, details: { picked: p }, feedback: name ? `You picked ${the(name)}; the target is ${the(key.answer)}.` : `That's not it; the target is ${the(key.answer)}.` };
}

const placed = Array.isArray(answer?.placed) ? answer.placed : [];
const pins = (key.names ?? []).map((correct, i) => {
  const given = placed[i] ?? null;
  return { given, correct, ok: given != null && norm(given) === norm(correct) && !sideClash(given, correct) };
});
const right = pins.filter((p) => p.ok).length;
const empty = pins.filter((p) => p.given == null).length;
const wrong = pins.map((p, i) => (!p.ok && p.given != null ? `${p.given} isn't pin ${i + 1}, that's ${the(p.correct)}` : null)).filter(Boolean);
const feedback = right === pins.length ? "All pins right."
  : [`${right} of ${pins.length} right.`, ...wrong.map((w) => w + "."), empty ? `${empty} left empty.` : ""].filter(Boolean).join(" ");
return { score: pins.length ? right / pins.length : 0, details: { pins }, feedback };

type.prepare:
// The scene asset only has geometry and a tissue per part, in a fixed order. Which part is which
// (keys, labels) lives in private fields written by build.py, so nothing in view names a part.
const MODES = ["name", "choose", "locate", "label"];
const mode = MODES.includes(fields.mode) ? fields.mode : "name";
const keys = fields.keys ?? [];
const labels = fields.labels ?? [];
const ix = (list) => (list ?? []).map((k) => keys.indexOf(k)).filter((i) => i >= 0);
const target = ix(fields.target);
const answer = fields.answer || labels[target[0]] || "";
const cam = fields.view && typeof fields.view === "object" ? fields.view : null;
const view = {
  mode, scene: fields.scene ?? "", region: fields.region ?? "", prompt: fields.prompt ?? "",
  xray: fields.xray === true && mode !== "locate", hide: ix(fields.hide), cam,
};
const key = { mode, labels, answer, target, note: fields.note ?? "" };
if (mode === "name") {
  view.target = target;
  key.accept = [answer, ...(fields.accept ?? [])].filter(Boolean);
} else if (mode === "choose") {
  view.target = target;
  const seen = new Set();
  view.options = rng.shuffle([answer, ...(fields.choices ?? [])].filter((o) => o && !seen.has(o) && seen.add(o)));
} else if (mode === "label") {
  const pins = fields.pins ?? [];
  const at = fields.anchors ?? [];
  view.pins = pins.map((k, i) => ({ part: keys.indexOf(k), at: at[i] }));
  key.names = pins.map((k) => labels[keys.indexOf(k)] ?? k);
  view.bank = rng.shuffle([...key.names, ...(fields.distractors ?? [])]);
  key.answer = "";
}
return { view, key };

type.demo:
// An example answer for watch mode.
if (view.mode === "name" || view.mode === "choose") return key.answer;
if (view.mode === "locate") return { part: key.target[0] };
return { placed: key.names.slice() };

template.css:
.a3-head { display: flex; flex-direction: column; gap: 0.2rem; }
.a3-eyebrow { font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--highlight); }
.a3-prompt { font-size: 1.1rem; }

.a3-stage {
  position: relative; width: 100%; aspect-ratio: 4 / 3; max-height: 30rem; overflow: hidden; touch-action: none; user-select: none; -webkit-user-select: none;
  border-radius: calc(var(--radius) + 4px); border: 1px solid var(--border);
  background:
    radial-gradient(ellipse 70% 60% at 50% 42%, color-mix(in oklab, var(--foreground) 7%, transparent), transparent 75%),
    color-mix(in oklab, var(--foreground) 2.5%, var(--card));
}
@media (max-width: 520px) { .a3-stage { aspect-ratio: 1 / 1; max-height: none; } }
.a3-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: grab; outline: none; }
.a3-canvas:active { cursor: grabbing; }
.a3-canvas:focus-visible { box-shadow: inset 0 0 0 2px var(--ring); }
.a3-stage.explore .a3-canvas { cursor: pointer; }
.a3-nogl { padding: 2rem; text-align: center; }

.a3-tools { position: absolute; right: 0.5rem; top: 0.5rem; display: flex; flex-direction: column; gap: 0.3rem; }
.a3-tool {
  width: 2rem; height: 2rem; display: grid; place-items: center; padding: 0; cursor: pointer;
  border: 1px solid var(--border); border-radius: calc(var(--radius) - 2px);
  background: color-mix(in oklab, var(--card) 82%, transparent); color: var(--muted-foreground);
  backdrop-filter: blur(6px);
}
.a3-tool:hover { color: var(--foreground); background: var(--card); }
.a3-tool[aria-pressed="true"] { color: var(--highlight); border-color: color-mix(in oklab, var(--highlight) 60%, var(--border)); }
.a3-tool svg { width: 1rem; height: 1rem; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
@media (pointer: coarse) { .a3-tool { width: 2.6rem; height: 2.6rem; } }
.a3-hint {
  position: absolute; left: 50%; bottom: 0.6rem; transform: translateX(-50%); pointer-events: none; white-space: nowrap;
  font-size: 0.75rem; color: var(--muted-foreground); opacity: 0.85; transition: opacity 0.5s;
}
.a3-stage.used .a3-hint { opacity: 0; }

/* Pins: a dot on the surface, a hairline, and a numbered tag pushed outward. */
.a3-lines { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; }
.a3-line { stroke: var(--foreground); stroke-width: 1.5; opacity: 0.9; filter: drop-shadow(0 0 1.5px color-mix(in oklab, var(--background) 90%, transparent)); }
.a3-line.behind { opacity: 0.18; stroke-dasharray: 3 3; }
.a3-pins { position: absolute; inset: 0; pointer-events: none; }
.a3-dot {
  position: absolute; left: 0; top: 0; width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px; border-radius: 50%;
  background: var(--foreground); box-shadow: 0 0 0 2px color-mix(in oklab, var(--background) 80%, transparent);
}
.a3-dot.behind { opacity: 0.3; }
.a3-tag {
  position: absolute; left: 0; top: 0; pointer-events: auto; cursor: pointer;
  display: flex; align-items: center; gap: 0.4rem; max-width: 15rem; min-height: 28px;
  translate: -50% -50%; padding: 0.15rem 0.2rem; border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 30%, transparent);
  background: color-mix(in oklab, var(--card) 96%, transparent); color: var(--foreground); backdrop-filter: blur(6px);
  font: 600 0.8rem/1.2 var(--font-sans); transition: border-color 0.15s, background 0.15s, opacity 0.2s;
}
.a3-tag.behind { opacity: 0.45; }
.a3-tag-n, .a3-num {
  flex: none; width: 1.4rem; height: 1.4rem; border-radius: 50%; display: grid; place-items: center;
  background: var(--foreground); color: var(--background); font: 700 0.78rem/1 var(--font-sans); font-variant-numeric: tabular-nums;
}
.a3-tag-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding-right: 0.45rem; min-width: 0; }
.a3-tag-name:empty { display: none; }
.a3-tag.over, .a3-slot.over { border-color: var(--highlight); background: color-mix(in oklab, var(--highlight) 18%, var(--card)); }
.a3-tag.is-correct { border-color: var(--success); }
.a3-tag.is-correct .a3-tag-n { background: var(--success); }
.a3-tag.is-wrong { border-color: var(--danger); }
.a3-tag.is-wrong .a3-tag-n { background: var(--danger); }
@media (max-width: 520px) { .a3-tag-name { display: none; } }

.a3-tip {
  position: absolute; left: 0; top: 0; translate: -50% -100%; pointer-events: none; white-space: nowrap;
  padding: 0.3rem 0.6rem; border-radius: calc(var(--radius) - 2px);
  background: var(--popover); color: var(--popover-foreground); border: 1px solid var(--border);
  font: 600 0.85rem/1.2 var(--font-sans); box-shadow: 0 6px 20px -8px rgb(0 0 0 / 0.5);
}

.a3-in { font-size: 1.1rem; max-width: 26rem; }
.a3-in.a3-partial { border-color: var(--warning); box-shadow: 0 0 0 1px color-mix(in oklab, var(--warning) 45%, transparent); }

.a3-slots { display: grid; grid-template-columns: repeat(auto-fill, minmax(13rem, 1fr)); gap: 0.45rem; }
.a3-slot {
  display: flex; align-items: center; gap: 0.6rem; min-height: 44px; padding: 0.4rem 0.7rem 0.4rem 0.45rem; text-align: left; cursor: pointer;
  border: 1px dashed color-mix(in oklab, var(--foreground) 32%, transparent); border-radius: var(--radius);
  background: transparent; color: var(--muted-foreground); font: 500 0.95rem/1.25 var(--font-sans);
}
.a3-slot.filled { border-style: solid; color: var(--foreground); background: color-mix(in oklab, var(--foreground) 5%, transparent); }
.a3-slot.is-correct { border-color: var(--success); background: color-mix(in oklab, var(--success) 12%, transparent); }
.a3-slot.is-correct .a3-num { background: var(--success); }
.a3-slot.is-wrong { border-color: var(--danger); background: color-mix(in oklab, var(--danger) 10%, transparent); color: var(--foreground); }
.a3-slot.is-wrong .a3-num { background: var(--danger); }
.a3-slot s { color: var(--muted-foreground); margin-right: 0.3rem; }
.a3-bank { display: flex; flex-wrap: wrap; gap: 0.45rem; margin-bottom: 0.7rem; }
.a3-chip {
  min-height: 40px; padding: 0.45rem 0.85rem; border-radius: 999px; cursor: grab; touch-action: none;
  border: 1px solid var(--border); background: color-mix(in oklab, var(--foreground) 6%, var(--card)); color: var(--foreground);
  font: 500 0.92rem/1.2 var(--font-sans); transition: opacity 0.15s, background 0.15s;
}
.a3-chip:hover { background: color-mix(in oklab, var(--foreground) 11%, var(--card)); }
.a3-chip[aria-pressed="true"] { border-color: var(--highlight); background: color-mix(in oklab, var(--highlight) 22%, var(--card)); }
.a3-chip.used, .a3-chip.dragging { opacity: 0.35; }
.a3-chip:disabled { cursor: default; opacity: 0.45; }
.a3-ghost { position: fixed; left: 0; top: 0; z-index: 50; pointer-events: none; opacity: 0.95; box-shadow: 0 10px 28px -10px rgb(0 0 0 / 0.6); border-color: var(--highlight); }

/* Loading and failure inside the stage. */
.a3-loading {
  position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.7rem;
  color: var(--muted-foreground); font: 500 0.85rem/1.2 var(--font-sans); pointer-events: none;
}
.a3-spin {
  width: 1.6rem; height: 1.6rem; border-radius: 50%;
  border: 2px solid color-mix(in oklab, var(--foreground) 14%, transparent); border-top-color: var(--highlight);
  animation: a3-spin 0.8s linear infinite;
}
@keyframes a3-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .a3-spin { animation-duration: 2.4s; } }
.a3-stage:has(.a3-loading) .a3-tools, .a3-stage:has(.a3-loading) .a3-hint { visibility: hidden; }
.a3-stage.failed { display: grid; place-items: center; aspect-ratio: auto; min-height: 10rem; }
.a3-error { display: flex; flex-direction: column; gap: 0.3rem; padding: 1.5rem; text-align: center; color: var(--muted-foreground); font-size: 0.9rem; }
.a3-error strong { color: var(--foreground); }

/* choose */
.a3-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.45rem; }
@media (max-width: 520px) { .a3-options { grid-template-columns: 1fr; } }
.a3-option { justify-content: flex-start; text-align: left; }
.a3-option[aria-pressed="true"]:not(.is-correct):not(.is-wrong) { border-color: var(--highlight); background: color-mix(in oklab, var(--highlight) 14%, var(--card)); }
.a3-work { padding-bottom: 1rem; }
/* label: a shorter stage so the name bank and the slots fit above the app's footer; room under the last row */
.a3-stage[data-mode="label"] { max-height: 26rem; }
.a3-work:has(.a3-slots) { padding-bottom: 2.5rem; }

.a3-stage [hidden], .a3-work [hidden] { display: none !important; }

/* locate */
.a3-pickbar { display: flex; align-items: center; gap: 0.6rem; min-height: 2.2rem; flex-wrap: wrap; }
.a3-pick {
  display: inline-flex; align-items: center; gap: 0.45rem; padding: 0.3rem 0.75rem; border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--highlight) 60%, var(--border)); background: color-mix(in oklab, var(--highlight) 16%, var(--card));
  color: var(--foreground); font: 600 0.88rem/1.2 var(--font-sans);
}
.a3-pick-dot { width: 0.6rem; height: 0.6rem; border-radius: 50%; background: var(--highlight); }
.a3-pickhint { font-size: 0.85rem; }
.a3-stage[data-mode="locate"] .a3-canvas { cursor: crosshair; }
.a3-stage[data-mode="locate"] .a3-canvas:active { cursor: grabbing; }
.a3-stage.explore .a3-canvas { cursor: pointer; }
.a3-tip.is-wrong { border-color: var(--danger); }

.a3-ans { font-size: 1.2rem; font-weight: 600; }
.a3-explore { font-size: 0.85rem; margin: 0; }
.a3-tool:focus:not(:focus-visible) { outline: none; box-shadow: none; }

template.js:
// Anatomy 3D: a small WebGL 2 viewer (no library) plus four ways to answer.
//   name   — the target parts glow; type the structure's name.
//   choose — the target parts glow; pick its name from the options (keys 1–4).
//   locate — the prompt describes a structure; tap it on the model.
//   label  — numbered pins sit on the model; drag (or tap, then tap) names onto them.
// The scene is a type asset (scene-<id>.bin) shared by every card; it holds geometry and tissue only.
const { view } = etude;
const stage = etude.$(".a3-stage");
const canvas = etude.$(".a3-canvas");
const pinsEl = etude.$(".a3-pins");
const linesEl = etude.$(".a3-lines");
const tip = etude.$(".a3-tip");
const work = etude.$(".a3-work");
const mode = ["name", "choose", "locate", "label"].includes(view.mode) ? view.mode : "name";
stage.dataset.mode = mode;

// ------------------------------------------------------------------ colours
// Muted, atlas-like tissue colours. They are lit and rim-shaded, so they read on dark and light cards.
const TISSUE = {
  bone: "#e4d9c0", cartilage: "#a9c4c6", tooth: "#f2ede0", tendon: "#d8d0bc", ligament: "#c2b994", fat: "#e6cf7c",
  muscle0: "#b9554a", muscle1: "#a4473f", muscle2: "#c6685a",
  nerve: "#e3c75a", artery: "#c9463b", vein: "#4c64a6", pulm: "#5b78b8", heart: "#ab463c",
  gyrus0: "#e2b3aa", gyrus1: "#d3a198", gyrus2: "#e9c2b6", cerebellum: "#cf9893", stem: "#c49488",
  deep0: "#b98a76", deep1: "#9a7b98", deep2: "#c8a16b", csf: "#6aa7d6",
  liver: "#8f3f2e", liver2: "#a5513b", gall: "#5f9550", gut: "#da9985", gut2: "#cc8a76", colon: "#d2a084", pancreas: "#e1b56f", spleen: "#7e3f59",
  kidney: "#9f4e3c", bladder: "#d5a48c", repro: "#c78b9b", gland: "#bf7158",
  lung: "#dba7a1", airway: "#c6d3d3",
};
const probe = document.createElement("canvas").getContext("2d", { willReadFrequently: true });
const rgb = (css, fallback = [0.9, 0.3, 0.6]) => {
  if (!css || !css.trim()) return fallback;
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = "#000"; probe.fillStyle = css.trim();
  probe.fillRect(0, 0, 1, 1);
  const d = probe.getImageData(0, 0, 1, 1).data;
  return [d[0] / 255, d[1] / 255, d[2] / 255];
};
let HL = [0.9, 0.3, 0.6], GOOD = [0.3, 0.75, 0.45], BAD = [0.85, 0.3, 0.3], DARK = true;
let dirty = true;
const readTheme = () => {
  const cs = getComputedStyle(document.documentElement);
  HL = rgb(cs.getPropertyValue("--highlight"), HL);
  GOOD = rgb(cs.getPropertyValue("--success"), GOOD);
  BAD = rgb(cs.getPropertyValue("--danger"), BAD);
  const bg = rgb(cs.getPropertyValue("--background"), [0, 0, 0]);
  DARK = bg[0] * 0.3 + bg[1] * 0.59 + bg[2] * 0.11 < 0.5;
  dirty = true;
};

// ------------------------------------------------------------------ state shared by the answer UI and the viewer
let result = null;          // { grade, key } once graded
let labels = [];            // part names, only after grading
let picked = -1;            // locate: the part the learner tapped
let pickAt = null;          // locate: where (CSS px), for the name tip after grading
let ready3d = false;
let pickTip = null;         // locate, after a wrong pick: the picked part's name, pinned to that part
const answered = () => etude.mode !== "answer";
const hidden = new Set((view.hide ?? []).map(Number));
const targets = new Set((view.target ?? []).map(Number)); // name/choose only; locate gets them after grading
const pinned = new Set((view.pins ?? []).map((p) => Number(p.part)));
const focus = mode === "label" ? pinned : targets;
let xray = view.xray === true && mode !== "locate";
let selected = -1, hovered = -1;
let placePins = () => {};
// Pin tags show a short form of long names: "Fifth lumbar vertebra (L5)" → "L5", "Anterior interventricular
// artery (LAD)" → "LAD". The slot list under the model keeps the full name.
const short = (n) => {
  const m = /^(.{18,}?)\s*\(([A-Z][A-Za-z0-9]{0,4})\)$/.exec(n);
  return m ? m[2] : n;
};


// ------------------------------------------------------------------ answer UI (built before the model loads)
if (mode === "name") {
  work.innerHTML = `<input class="e-input a3-in" autocomplete="off" spellcheck="false" placeholder="Name the glowing structure" autofocus>`;
  const input = work.querySelector("input");
  if (typeof etude.answer === "string") input.value = etude.answer;
  const sync = () => etude.setReady(input.value.trim().length > 0);
  input.addEventListener("input", sync);
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); etude.submit(); } });
  sync();
  etude.getAnswer(() => input.value);
  etude.onResult(({ grade }) => {
    input.disabled = true;
    if (grade) input.classList.add(grade.score >= 1 ? "is-correct" : grade.score > 0 ? "a3-partial" : "is-wrong");
  });
} else if (mode === "choose") {
  const opts = view.options ?? [];
  work.innerHTML = `<div class="a3-options" role="radiogroup" aria-label="Options">${opts.map((o, i) =>
    `<button type="button" class="e-option a3-option" role="radio" aria-checked="false" aria-pressed="false" data-i="${i}">${i < 9 ? `<span class="e-key">${i + 1}</span>` : ""}<span>${etude.escape(o)}</span></button>`).join("")}</div>`;
  const buttons = etude.$$(".a3-option");
  let choice = null;
  const choose = (i) => {
    if (answered() || !buttons[i]) return;
    choice = opts[i];
    buttons.forEach((b, j) => { b.setAttribute("aria-pressed", String(j === i)); b.setAttribute("aria-checked", String(j === i)); });
    etude.setReady(true);
  };
  buttons.forEach((b, i) => b.addEventListener("click", () => choose(i)));
  window.addEventListener("keydown", (e) => {
    if (answered() || e.target?.tagName === "INPUT" || e.metaKey || e.ctrlKey || e.altKey) return;
    const n = Number(e.key);
    if (n >= 1 && n <= buttons.length) { e.preventDefault(); choose(n - 1); buttons[n - 1].focus(); }
  });
  etude.setReady(false);
  if (typeof etude.answer === "string") { const i = opts.indexOf(etude.answer); if (i >= 0) choose(i); }
  etude.getAnswer(() => choice);
