  const pulsing = !answered() && targets.size && mode !== "locate";
  if (dirty || pulsing) {
    if (dirty) { updateCamera(); pickDirty = true; }
    draw(now);
    if (dirty) { placePins(); placePickTip(); }
    dirty = false;
  }
  requestAnimationFrame(frame);
};

// ------------------------------------------------------------------ controls
const pointers = new Map();
let drag = null, pinch = null;
const setCam = (az, el, zoom) => { cam.az = az; cam.el = Math.max(-85, Math.min(85, el)); cam.zoom = Math.max(0.55, Math.min(5, zoom)); tween = null; dirty = true; };
const local = (e) => { const r = stage.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; };
canvas.addEventListener("pointerdown", (e) => {
  canvas.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  if (pointers.size === 1) drag = { x: e.clientX, y: e.clientY, az: cam.az, el: cam.el, moved: 0 };
  if (pointers.size === 2) { const [a, b] = [...pointers.values()]; pinch = { d: Math.hypot(a.x - b.x, a.y - b.y), zoom: cam.zoom }; drag = null; }
});
canvas.addEventListener("pointermove", (e) => {
  if (pointers.has(e.pointerId)) pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  if (pinch && pointers.size === 2) {
    const [a, b] = [...pointers.values()];
    setCam(cam.az, cam.el, (pinch.zoom * Math.hypot(a.x - b.x, a.y - b.y)) / pinch.d);
  } else if (drag && pointers.has(e.pointerId)) {
    const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
    drag.moved = Math.max(drag.moved, Math.hypot(dx, dy));
    if (drag.moved >= 5) { setCam(drag.az - dx * 0.45, drag.el + dy * 0.45, cam.zoom); stage.classList.add("used"); }
  } else if (e.pointerType === "mouse") {
    if (answered()) explore(e, false);
    else if (mode === "locate") { const [x, y] = local(e); const id = partAt(x, y); if (id !== hovered) { hovered = id; dirty = true; } }
  }
});
const endPointer = (e) => {
  const wasTap = drag && drag.moved < 5 && pointers.size === 1;
  pointers.delete(e.pointerId);
  if (pointers.size < 2) pinch = null;
  if (pointers.size === 0) {
    if (wasTap && e.type === "pointerup") {
      if (answered()) explore(e, true);
      else if (mode === "locate") { const [x, y] = local(e); const id = partAt(x, y); if (id >= 0) setPick(id, [x, y]); }
    }
    drag = null;
  }
};
canvas.addEventListener("pointerup", endPointer);
canvas.addEventListener("pointercancel", endPointer);
canvas.addEventListener("pointerleave", () => { if (hovered !== -1 && selected === -1) { hovered = -1; if (answered()) tip.hidden = true; dirty = true; } });
canvas.addEventListener("wheel", (e) => {
  if (document.activeElement !== canvas && !stage.classList.contains("used")) return;
  e.preventDefault();
  setCam(cam.az, cam.el, cam.zoom * Math.exp(-e.deltaY * 0.0015));
}, { passive: false });
canvas.addEventListener("dblclick", () => { tween = { from: { ...cam }, to: { ...home }, t0: performance.now(), dur: 600 }; });
canvas.addEventListener("keydown", (e) => {
  const step = { ArrowLeft: [12, 0], ArrowRight: [-12, 0], ArrowUp: [0, -10], ArrowDown: [0, 10] }[e.key];
  if (step) { e.preventDefault(); setCam(cam.az + step[0], cam.el + step[1], cam.zoom); }
  else if (e.key === "+" || e.key === "=") { e.preventDefault(); setCam(cam.az, cam.el, cam.zoom * 1.2); }
  else if (e.key === "-" || e.key === "_") { e.preventDefault(); setCam(cam.az, cam.el, cam.zoom / 1.2); }
});
const xrayBtn = etude.$(".a3-tool[data-act=xray]");
xrayBtn?.setAttribute("aria-pressed", String(xray));
if (!focus.size && mode !== "locate") xrayBtn?.remove();
if (mode === "locate" && xrayBtn) xrayBtn.hidden = true; // no see-through before answering: it would hint at depth
for (const b of etude.$$(".a3-tool")) b.addEventListener("click", () => {
  if (b.dataset.act === "in") setCam(cam.az, cam.el, cam.zoom * 1.25);
  if (b.dataset.act === "out") setCam(cam.az, cam.el, cam.zoom / 1.25);
  if (b.dataset.act === "xray") { xray = !xray; b.setAttribute("aria-pressed", String(xray)); dirty = true; return; }
  if (b.dataset.act === "reset") tween = { from: { ...cam }, to: { ...home }, t0: performance.now(), dur: 600 };
});

// After answering: hover or tap a structure to see its name.
const showTip = (text, x, y, cls) => {
  tip.textContent = text;
  tip.className = `a3-tip${cls ? ` is-${cls}` : ""}`;
  tip.hidden = false;
  tip.style.left = `${Math.min(W - 8, Math.max(8, x))}px`;
  tip.style.top = `${Math.max(8, y - 14)}px`;
};
// Wrong pick in locate: its name stays on the model (at the part's on-screen centre) until the learner explores.
const placePickTip = () => {
  if (!pickTip || selected !== -1 || hovered !== -1 || picked < 0) return;
  const p = parts[picked];
  let sx = 0, sy = 0, n = 0;
  const step = Math.max(1, Math.floor(p.pos.length / 3 / 200));
  for (let i = 0; i < p.pos.length; i += 3 * step) { const s = project([p.pos[i], p.pos[i + 1], p.pos[i + 2]]); sx += s[0]; sy += s[1]; n++; }
  if (n) showTip(pickTip, sx / n, sy / n, "wrong");
};
const explore = (e, tap) => {
  pickTip = null;
  const [x, y] = local(e);
  const id = partAt(x, y);
  if (tap) selected = id === selected ? -1 : id;
  else hovered = id;
  const show = tap ? selected : (selected !== -1 ? selected : hovered);
  if (show >= 0 && labels[show]) showTip(labels[show], x, y);
  else tip.hidden = true;
  dirty = true;
};

// ------------------------------------------------------------------ pins (label mode)
const pins = (view.pins ?? []).filter((p) => Array.isArray(p.at)).map((p, i) => ({ ...p, part: Number(p.part), n: i + 1, m: toModel(p.at) }));
const placed = Array(pins.length).fill(null);
let held = null;
const svg = (tag, attrs) => { const el = document.createElementNS("http://www.w3.org/2000/svg", tag); for (const k in attrs) el.setAttribute(k, attrs[k]); return el; };
for (const p of pins) {
  p.dot = Object.assign(document.createElement("div"), { className: "a3-dot" });
  p.tag = document.createElement("button");
  p.tag.type = "button"; p.tag.className = "a3-tag"; p.tag.dataset.pin = String(p.n - 1);
  p.tag.innerHTML = `<span class="a3-tag-n">${p.n}</span><span class="a3-tag-name"></span>`;
  p.line = svg("line", { class: "a3-line" });
  linesEl.append(p.line);
  pinsEl.append(p.dot, p.tag);
}
placePins = () => {
  if (!pins.length) return;
  const c = project(fitShift);
  // Silhouette radius in each direction, from the sampled vertices, so tags sit just outside the model.
  const ring = new Float32Array(24);
  for (let i = 0; i < sample.length; i += 2) {
    const s = project(sample[i]); const dx = s[0] - c[0], dy = s[1] - c[1];
    const a = Math.floor(((Math.atan2(dy, dx) + Math.PI) / (2 * Math.PI)) * 24) % 24;
    ring[a] = Math.max(ring[a], Math.hypot(dx, dy));
  }
  const sp = pins.map((p) => ({ p, s: project(p.m) }));
  const ringAt = (ang) => { const a = Math.floor(((ang + Math.PI) / (2 * Math.PI)) * 24) % 24; return Math.max(ring[a], ring[(a + 1) % 24], ring[(a + 23) % 24]); };
  // Radial labels: each tag goes out along its pin's direction, just past the silhouette. Tags keep the
  // pins' angular order and are spread to a minimum arc, so leader lines never cross or run under a tag.
  const tags = sp.map(({ p, s }) => ({ p, s, ang: Math.atan2(s[1] - c[1], s[0] - c[0]), w: (p.tag.offsetWidth || 30) + 12, h: (p.tag.offsetHeight || 28) + 10 }));
  tags.sort((a, b) => a.ang - b.ang);
  const R0 = Math.max(...tags.map((t) => ringAt(t.ang))) + 30;
  for (let it = 0; it < 80; it++) {
    let moved = false;
    for (let i = 0; i < tags.length; i++) {
      const a = tags[i], b = tags[(i + 1) % tags.length];
      if (tags.length < 2 || (i === tags.length - 1 && tags.length < 3)) continue;
      let gap = b.ang - a.ang; if (gap <= 0) gap += 2 * Math.PI;
      const midA = (a.ang + gap / 2);
      const across = Math.abs(Math.sin(midA)) * (a.w + b.w) / 2 + Math.abs(Math.cos(midA)) * (a.h + b.h) / 2;
      const need = across / R0;
      if (gap < need) { const k = (need - gap) / 2; a.ang -= k; b.ang += k; moved = true; }
    }
    if (!moved) break;
  }
  for (const t of tags) {
    const r = Math.max(Math.hypot(t.s[0] - c[0], t.s[1] - c[1]) + 30, ringAt(t.ang) + 24 + Math.abs(Math.cos(t.ang)) * t.w / 2 * 0.6);
    t.x = c[0] + Math.cos(t.ang) * r; t.y = c[1] + Math.sin(t.ang) * r;
    t.x = Math.min(W - t.w / 2 - 4, Math.max(t.w / 2 + 4, t.x)); t.y = Math.min(H - t.h / 2 - (stage.classList.contains("used") ? 4 : 36), Math.max(t.h / 2 + 4, t.y));
  }
  // Clamping to the stage can stack tags (tall models, pins near the bottom). Push overlapping tags
  // apart, sideways first: tall models leave room left and right.
  const yMax = H - (stage.classList.contains("used") ? 4 : 36);
  for (let it = 0; it < 60; it++) {
    let moved = false;
    for (let i = 0; i < tags.length; i++) for (let j = i + 1; j < tags.length; j++) {
      const a = tags[i], b = tags[j];
      const ox = (a.w + b.w) / 2 - Math.abs(a.x - b.x), oy = (a.h + b.h) / 2 - Math.abs(a.y - b.y);
      if (ox <= 0 || oy <= 0) continue;
      moved = true;
      if (ox <= oy * 2.5) { const k = ox / 2 + 1, sx = a.x <= b.x ? -1 : 1; a.x += sx * k; b.x -= sx * k; }
      else { const k = oy / 2 + 1, sy = a.y <= b.y ? -1 : 1; a.y += sy * k; b.y -= sy * k; }
      for (const t of [a, b]) {
        t.x = Math.min(W - t.w / 2 - 4, Math.max(t.w / 2 + 4, t.x));
        t.y = Math.min(yMax - t.h / 2, Math.max(t.h / 2 + 4, t.y));
      }
    }
    if (!moved) break;
  }
  for (const t of tags) {
    const seen = xray || partsAt(t.s[0], t.s[1]).includes(t.p.part);
    t.p.dot.style.transform = `translate(${t.s[0]}px, ${t.s[1]}px)`;
    t.p.tag.style.transform = `translate(${t.x}px, ${t.y}px)`;
    t.p.dot.classList.toggle("behind", !seen);
    t.p.tag.classList.toggle("behind", !seen);
    t.p.line.classList.toggle("behind", !seen);
    t.p.line.setAttribute("x1", t.s[0]); t.p.line.setAttribute("y1", t.s[1]);
    t.p.line.setAttribute("x2", t.x); t.p.line.setAttribute("y2", t.y);
  }
};

if (mode === "label") {
  work.innerHTML = `
    <div class="a3-bank" aria-label="Names">${(view.bank ?? []).map((n) => `<button type="button" class="a3-chip">${etude.escape(n)}</button>`).join("")}</div>
    <div class="a3-slots">${pins.map((p) => `<button type="button" class="a3-slot" data-pin="${p.n - 1}"><span class="a3-num">${p.n}</span><span class="a3-slot-name">Drop a name here</span></button>`).join("")}</div>`;
  const chips = etude.$$(".a3-chip");
  const slots = etude.$$(".a3-slot");
  const render = () => {
    slots.forEach((s, i) => {
      s.classList.toggle("filled", !!placed[i]);
      s.querySelector(".a3-slot-name").textContent = placed[i] ?? "Drop a name here";
    });
    pins.forEach((p, i) => { p.tag.classList.toggle("filled", !!placed[i]); p.tag.querySelector(".a3-tag-name").textContent = placed[i] ? short(placed[i]) : ""; p.tag.title = placed[i] ?? `Pin ${p.n}`; });
    chips.forEach((c) => { c.classList.toggle("used", placed.includes(c.textContent)); c.setAttribute("aria-pressed", String(c === held)); });
    if (!answered()) etude.setReady(placed.some(Boolean));
    requestAnimationFrame(placePins);
  };
  const put = (name, i) => {
    const was = placed.indexOf(name);
    if (was !== -1) placed[was] = null;
    placed[i] = name;
    held = null;
    render();
  };
  const targetAt = (x, y) => document.elementFromPoint(x, y)?.closest("[data-pin]");
  const onTarget = (el) => {
    if (answered()) return;
    const i = Number(el.dataset.pin);
    if (held) put(held.textContent, i);
    else if (placed[i]) { placed[i] = null; render(); }
  };
  for (const el of [...slots, ...pins.map((p) => p.tag)]) el.addEventListener("click", () => onTarget(el));
  for (const chip of chips) {
    chip.addEventListener("pointerdown", (e) => {
      if (answered() || e.button > 0) return;
      const start = { x: e.clientX, y: e.clientY };
      let ghost = null, over = null;
      const move = (ev) => {
        if (!ghost && Math.hypot(ev.clientX - start.x, ev.clientY - start.y) < 6) return;
        if (!ghost) { ghost = chip.cloneNode(true); ghost.className = "a3-chip a3-ghost"; document.body.append(ghost); chip.classList.add("dragging"); }
        ghost.style.transform = `translate(${ev.clientX}px, ${ev.clientY}px) translate(-50%, -60%)`;
        const t = targetAt(ev.clientX, ev.clientY);
        if (t !== over) { over?.classList.remove("over"); over = t; over?.classList.add("over"); for (const p of pins) p.tag.classList.toggle("over", !!over && p.tag.dataset.pin === over.dataset.pin); for (const s of slots) s.classList.toggle("over", !!over && s.dataset.pin === over.dataset.pin); }
      };
      const up = (ev) => {
        window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); window.removeEventListener("pointercancel", up);
        for (const el of [...slots, ...pins.map((p) => p.tag)]) el.classList.remove("over");
        if (ghost) {
          ghost.remove(); chip.classList.remove("dragging");
          const t = targetAt(ev.clientX, ev.clientY);
          if (t) put(chip.textContent, Number(t.dataset.pin));
          chip.dataset.dragged = "1";
        }
      };
      window.addEventListener("pointermove", move); window.addEventListener("pointerup", up); window.addEventListener("pointercancel", up);
    });
    chip.addEventListener("click", () => {
      if (chip.dataset.dragged) { delete chip.dataset.dragged; return; }
      if (answered()) return;
      held = held === chip ? null : chip;
      render();
    });
  }
  if (etude.answer?.placed) etude.answer.placed.forEach((n, i) => { if (i < placed.length) placed[i] = n; });
  render();
  etude.getAnswer(() => ({ placed: placed.slice() }));
  etude.onResult(({ grade, answer }) => {
    if (answer?.placed) answer.placed.forEach((n, i) => { if (i < placed.length) placed[i] = n; });
    render();
    const res = grade?.details?.pins ?? [];
    res.forEach((r, i) => {
      const cls = r.ok ? "is-correct" : "is-wrong";
      slots[i]?.classList.add(cls); pins[i]?.tag.classList.add(cls);
      if (!r.ok && slots[i]) slots[i].querySelector(".a3-slot-name").innerHTML = r.given
        ? `<s>${etude.escape(r.given)}</s> ${etude.escape(r.correct)}` : etude.escape(r.correct);
      if (!r.ok && pins[i]) { pins[i].tag.querySelector(".a3-tag-name").textContent = short(r.correct); pins[i].tag.title = r.correct; }
    });
    for (const c of chips) c.disabled = true;
    requestAnimationFrame(placePins);
  });
}

if (mode === "locate" && !answered() && Number.isInteger(etude.answer?.part) && etude.answer.part >= 0) setPick(etude.answer.part);
ready3d = true;
readTheme();
new MutationObserver(readTheme).observe(document.head, { subtree: true, childList: true, characterData: true, attributes: true });
new MutationObserver(readTheme).observe(document.documentElement, { attributes: true, attributeFilter: ["style", "class", "data-theme"] });
resize();
applyResult();
requestAnimationFrame(frame);
